insert into programs (id, version, name, definition) values
  ('upper-lower-4day', 1, 'Upper / lower, four day', '{"id":"upper-lower-4day","version":1,"name":"Upper / lower, four day","blocks":8,"slots":[{"kind":"lift","key":"U1"},{"kind":"lift","key":"L1"},{"kind":"steady"},{"kind":"lift","key":"U2"},{"kind":"lift","key":"L2"}],"phases":[{"id":"accumulate","name":"Accumulate","color":"#2F6BB0","kg":"20","from":0,"to":19,"note":"Build volume. Add a set before you add load."},{"id":"intensify","name":"Intensify","color":"#C93A2B","kg":"25","from":20,"to":39,"note":"Volume comes down, load goes up. Leave a rep in reserve on everything but the last set."}],"tech":{"drop":{"label":"Drop set","when":"Final set only","steps":["Hit the stall point.","Strip 25-30% immediately.","Go again to the stall point."]}},"sessions":{"U1":{"letter":"U1","title":"Upper — push focus","sub":"Press first","ex":[{"id":"flat-barbell-bench","name":"Flat barbell bench","sets":4,"reps":"6-8","rest":120,"pair":null},{"id":"barbell-row","name":"Barbell row","sets":4,"reps":"8-10","rest":90,"pair":null},{"id":"arnold-press","name":"Arnold press","sets":3,"reps":"10-12","rest":75,"pair":null},{"id":"rope-pushdown","name":"Rope pushdown","sets":3,"reps":"12-15","rest":60,"pair":1},{"id":"barbell-curl","name":"Barbell curl","sets":3,"reps":"10","rest":60,"pair":1}]},"L1":{"letter":"L1","title":"Lower — squat focus","sub":"Heavy, then accessories","ex":[{"id":"back-squat","name":"Back squat","sets":4,"reps":"5-6","rest":150,"pair":null},{"id":"romanian-deadlift","name":"Romanian deadlift","sets":3,"reps":"8-10","rest":90,"pair":null},{"id":"leg-press","name":"Leg press","sets":3,"reps":"12-15","rest":75,"pair":null,"tech":"drop"},{"id":"standing-calf-raise","name":"Standing calf raise","sets":4,"reps":"15-20","rest":45,"pair":null}]},"U2":{"letter":"U2","title":"Upper — pull focus","sub":"Vertical pulling first","ex":[{"id":"wide-grip-pulldown","name":"Wide-grip pull-up / pulldown","sets":4,"reps":"6-10","rest":90,"pair":null},{"id":"incline-barbell-press","name":"Incline barbell press","sets":4,"reps":"8-10","rest":90,"pair":null},{"id":"chest-supported-row","name":"Chest-supported row","sets":3,"reps":"10-12","rest":75,"pair":null},{"id":"lateral-raise","name":"Lateral raise","sets":4,"reps":"12-15","rest":45,"pair":1},{"id":"hammer-curl","name":"Hammer curl","sets":3,"reps":"12","rest":45,"pair":1}]},"L2":{"letter":"L2","title":"Lower — hinge focus","sub":"Posterior chain","ex":[{"id":"deadlift","name":"Deadlift","sets":3,"reps":"4-6","rest":180,"pair":null},{"id":"front-squat","name":"Front squat","sets":3,"reps":"8-10","rest":120,"pair":null},{"id":"lying-leg-curl","name":"Lying leg curl","sets":3,"reps":"12","rest":60,"pair":null},{"id":"hanging-knee-raise","name":"Hanging knee raise","sets":3,"reps":"12-15","rest":45,"pair":null}]}},"modes":{"run":{"label":"Run","protocol":"30-40 min easy","unit":"km"},"rower":{"label":"Rower","protocol":"8 x 30 s hard / 90 s easy","unit":"m"},"ski":{"label":"Ski erg","protocol":"8 x 30 s hard / 90 s easy","unit":"m"},"bike":{"label":"Bike","protocol":"30-40 min easy","unit":"km"}}}'::jsonb)
